                    payload.insert("file_id".to_string(), r::to_json(&r::field(row, "file_id")));
                    payload.insert("user_id".to_string(), r::to_json(&r::field(row, "user_id")));
                    payload.insert("parent_id".to_string(), r::to_json(&r::field(row, "parent_id")));
